slotConfig.value:
{
  "name": "_reasoning",
  "type": "string",
  "description": "In one sentence, justify your decision. If the USER’s request asks about the server’s current state, configuration, or requires running any command, you MUST explain why planning actions is needed. If the USER only asks for a theoretical clarification or conversational reply, explain why answering directly is enough."
  "nullable": false
}

{
  "name": "direct_answer",
  "type": "string",
  "description": "Only if you chose answer_directly: provide a concise 1–3 sentence reply. This is strictly for clarifications or general technical knowledge. Never use this for questions about the actual server state, because those require planning actions.",
  "nullable": true
}

{
  "name": "decision",
  "type": "string",
"description": "Choose your next step. If the USER’s request requires any inspection of the server, running commands, or interacting with system state, you MUST select plan_actions. Only use answer_directly for clarifications or knowledge that does not depend on the server.",
  "enum": [
    "answer_directly",
    "plan_actions"
  ],
  "nullable": false
}

{
  "name": "actions_plan_instruction",
  "type": "string",
  "description": "If you chose plan_actions, provide a clear 1–3 sentence instruction for the planner. The instruction must describe the USER’s request in terms of what needs to be checked or done on the server. Do not give a full plan yourself, only the instruction.",
  "nullable": true
}

{%- set analysis_msg = messages_bag.find_message_by_name('TOPIC_ANALYSIS') -%}
{%- if analysis_msg is not none -%}
  {%- set decision = analysis_msg.data_search('decision') -%}
  {{- decision is not none and decision.get_str() == 'answer_directly' -}}
{%- endif -%}

{
  "name": "_reasoning",
  "type": "string",
  "description": "In one or two sentences, explain why planning these actions is necessary at this point.",
  "nullable": false
}

{
  "name": "actions",
  "type": "array",
  "description": "An ordered list of simple, safe textual steps (e.g., do/check). Keep steps minimal. Never suggest unnecessary or extreme actions. One action is enough if sufficient. Maximum: 3 distinct actions, or up to 5 only if some are very similar.",
  "items": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "description": {
        "type": "string",
        "description": "Human-readable explanation of the step."
      },
      "tool": {
        "type": "string",
        "enum": ["shell", "http_request"],
        "description": "Tool to use for this action."
      },
      "arguments": {
        "type": "object",
        "additionalProperties": false,
        "description": "Tool-specific arguments. Provide only the field required by the selected tool.",
        "properties": {
          "argv": {
            "type": "array",
            "description": "Only when tool = shell. Command as a list of tokens (e.g., [\"ls\",\"-la\"]). Executed in Python with subprocess.run(command, shell=False). Do NOT use shell metacharacters because no shell is involved.",
            "items": {
              "type": "string",
              "pattern": "^[^|><;&\\s]+$",
              "description": "Single token (no spaces). Forbidden characters: | > < ; &"
            },
            "minItems": 1,
            "maxItems": 256,
            "nullable": true
          },
          "url": {
            "type": "string",
            "format": "uri",
            "description": "Only when tool = http_request. HTTP/HTTPS URL to fetch.",
            "nullable": true
          }
        }
      }
    },
    "required": ["description", "tool", "arguments"]
  },
  "minItems": 1,
  "maxItems": 5,
  "nullable": false
}

{%- set analysis_msg = messages_bag.find_message_by_name('TOPIC_ANALYSIS') -%}
{%- if analysis_msg is not none -%}
  {%- set decision = analysis_msg.data_search('decision') -%}
  {{- decision is not none and decision.get_str() == 'plan_actions' -}}
{%- endif -%}

{%- set last_action_plan = messages_bag.find_message_by_name('ACTIONS_PLAN') %}
{%- set has_no_terminate_reason = not last_action_plan or last_action_plan.data_search('termination_reason').is_none() -%}
{%- if has_no_terminate_reason: -%}
  ["CONTINUE_PLANNING"]
{%- else -%}
  []
{%- endif -%}

